var text = String(input.text || input.content || "");
var max = Number(input.maxLength || 200);
var normalized = text.replace(/\s+/g, " ").trim();
if (normalized.length <= max) return { summary: normalized, length: text.length, truncated: false };
var cut = normalized.slice(0, max);
var lastSpace = cut.lastIndexOf(" ");
if (lastSpace > max * 0.6) cut = cut.slice(0, lastSpace);
return { summary: cut + " ...", length: text.length, truncated: true };
